"""Frozen evidence and rollback boundaries for Task Breakdown operations."""
from contextlib import contextmanager
from functools import wraps
from agent_engine.phase4 import files
from agent_engine.phase4.evidence import SOURCES, frozen_text


def frozen_operation(fn):
    @wraps(fn)
    async def run(project, *args, **kwargs):
        if fn.__name__ == 'generate':
            from agent_engine.phase4 import speckit
            speckit.init(project)
        # The shared contract is generated by this operation; helpers freeze it
        # after the parent barrier. All externally owned inputs remain immutable.
        paths = [p for p in SOURCES if fn.__name__ != 'generate' or p != 'backlog/implementation-contract.md']
        paths += [files.PROJECT_SETTINGS, files.HISTORY]
        texts = {p: files.read_text(project, p) if files.exists(project, p) else None for p in paths}
        token = frozen_text.set((project, texts))
        try:
            result = await fn(project, *args, **kwargs)
            if any((files.read_text(project, p) if files.exists(project, p) else None) != text for p, text in texts.items()):
                raise files.ProjectError('source inputs changed during operation; completion refused')
            return result
        finally:
            frozen_text.reset(token)
    return run


@contextmanager
def artifact_transaction(project, directories):
    """Rollback ordinary errors/cancellation across a multi-feature repair.

    Individual writers retain their own atomic publication rules. No successful
    checkpoint can be accepted after a rolled-back output (hashes no longer match).
    """
    root = files.project_dir(project)
    old = {}
    for directory in directories:
        base = files.path(project, directory)
        for path in base.rglob('*') if base.is_dir() else [base]:
            if path.is_file():
                checked = files.path(project, path.relative_to(root).as_posix())
                old[checked] = checked.read_bytes()
    try:
        yield
    except BaseException:
        from agent_engine.phase4.feature_documents import _restore_bytes
        for directory in directories:
            base = files.path(project, directory)
            for path in base.rglob('*') if base.is_dir() else [base]:
                if path.is_file() and path not in old:
                    files.path(project, path.relative_to(root).as_posix()).unlink()
        for path, content in old.items():
            _restore_bytes(path, content)
        raise


def freeze_contract(project):
    frozen = frozen_text.get()
    if frozen is not None and frozen[0] == project:
        frozen[1]['backlog/implementation-contract.md'] = files.read_text(project, 'backlog/implementation-contract.md')
